package ai.eva.android.probe;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;
public class PhoneCheck extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 String find(JSONObject snapshot,String key,String value)throws Exception{JSONArray rows=snapshot.getJSONArray("nodes");for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).optString(key).equals(value))return rows.getJSONObject(i).getString("id");throw new Exception("node missing: "+value);}
 JSONObject run(String action)throws Exception{return PhoneTools.execute(getTargetContext(),new JSONObject().put("action",action));}
 public void onStart(){Bundle output=new Bundle();int code=0;Activity fixture=null;try{for(int i=0;i<50&&PhoneAccessibility.live==null;i++)Thread.sleep(100);if(PhoneAccessibility.live==null)throw new Exception("Accessibility not connected; user must enable Eva first");fixture=startActivitySync(new Intent(getTargetContext(),PhoneFixtureActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(600);PhoneAccessibility.armed=true;PhoneAccessibility.generation++;JSONObject screen=run("observe");if(!screen.getString("package").equals(getTargetContext().getPackageName()))throw new Exception("fixture not foreground");String input=find(screen,"description","fixture-input");PhoneTools.execute(getTargetContext(),new JSONObject().put("action","input").put("snapshot",screen.getString("snapshot")).put("node",input).put("text","phone-use-check"));screen=run("observe");find(screen,"text","phone-use-check");String button=find(screen,"text","fixture-click");PhoneTools.execute(getTargetContext(),new JSONObject().put("action","click").put("snapshot",screen.getString("snapshot")).put("node",button));Thread.sleep(300);screen=run("observe");find(screen,"text","fixture-clicked");if(!run("screenshot").getString("imageUrl").startsWith("data:image/jpeg;base64,"))throw new Exception("screenshot missing");PhoneAccessibility.stopControl();try{run("observe");throw new Exception("stopped control still readable");}catch(java.io.IOException expected){}PhoneShellService shell=new PhoneShellService();Parcel in=Parcel.obtain(),out=Parcel.obtain();try{in.writeInterfaceToken(PhoneShellService.TOKEN);in.writeString("printf eva-shell-fixture");shell.transact(1,in,out,0);out.readException();JSONObject result=new JSONObject(out.readString());if(!result.optString("output").equals("eva-shell-fixture")||result.optInt("exitCode",-1)!=0)throw new Exception("shell stream failed: "+result);if(result.getInt("uid")!=android.os.Process.myUid())throw new Exception("unexpected identity");}finally{in.recycle();out.recycle();}output.putString("result","PASS real phone: accessibility observe/input/click/screenshot on owned fixture; stop denies reads; shell Binder and streams tested as app UID only, not Shizuku/ADB authorization.");}catch(Exception e){code=1;output.putString("error",e.toString());}finally{PhoneAccessibility.stopControl();if(fixture!=null){final Activity a=fixture;runOnMainSync(a::finish);}}finish(code,output);}
}
